const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format((n||0)/100);
const exactMoney = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:2}).format((n||0)/100);
const fmtDate = d => d ? new Date(d.slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}) : '—';
const initials = name => name.split(' ').map(n=>n[0]).slice(0,2).join('');
const icons = {grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',repeat:'M17 2l4 4-4 4 M3 11V8a2 2 0 012-2h16 M7 22l-4-4 4-4 M21 13v3a2 2 0 01-2 2H3',box:'M12 3l9 5v8l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v8 M7 5.7l9 5',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',wallet:'M3 6h17v14H3z M3 6V4h14v2 M15 11h6v5h-6z',users:'M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2 M16 4a4 4 0 010 8 M22 21v-2a4 4 0 00-3-3.87 M13 7a4 4 0 11-8 0 4 4 0 018 0',chart:'M3 3v18h18 M7 14l4-5 4 3 6-8',settings:'M12 8a4 4 0 100 8 4 4 0 000-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M21 21l-5-5 M18 10a8 8 0 11-16 0 8 8 0 0116 0',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 5v14 M5 12h14',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',check:'M5 12l4 4L19 6',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',play:'M8 4l12 8-12 8z',clock:'M12 8v5l3 2 M22 12a10 10 0 11-20 0 10 10 0 0120 0',alert:'M12 3l10 18H2z M12 9v5 M12 17v1',logout:'M9 4H3v16h6 M8 12h14 M17 7l5 5-5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',close:'M6 6l12 12 M18 6L6 18',filter:'M3 5h18 M6 12h12 M10 19h4',menu:'M4 6h16 M4 12h16 M4 18h16',leaf:'M20 3C7 1 1 8 5 15s15 6 15-12z M4 21L16 8',mail:'M3 5h18v14H3z M3 5l9 8 9-8',dots:'M5 12h.01 M12 12h.01 M19 12h.01',trend:'M3 17l6-6 4 4 8-10 M15 5h6v6',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`;
const mark=()=>'<span class="brand-mark"><i></i><i></i><i></i></span>';
const brand=()=>`<div class="brand">${mark()}cadence<span style="color:#a3ad93;font-size:14px;margin-left:-7px">®</span></div>`;
const btn=(label,action,ic='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ic?icon(ic,14):''}${label}</button>`;
const badge=s=>`<span class="badge ${s.toLowerCase()}">${esc(s)}</span>`;
const colors=['#ecddcd','#e2e6d8','#eadde3','#e2e3f0','#e9e4d2','#d9e6e4'];
const avatar=(name,id=0)=>`<span class="avatar" style="background:${colors[id%colors.length]}">${esc(initials(name))}</span>`;
const customerCell=(name,sub='',id=0)=>`<div class="customer-cell">${avatar(name,id)}<div><strong>${esc(name)}</strong><small>${esc(sub)}</small></div></div>`;
let D, page='overview', subFilter='All', search='', chartMode='revenue', rehearsalDays=7, rehearsalData, loginMode='login', modalReturnFocus;
const labels={overview:'Overview',subscriptions:'Subscriptions',catalog:'Products & plans',invoices:'Invoices',payments:'Payments',customers:'Customers',rehearsal:'Billing rehearsal',reports:'Reports',settings:'Settings',activity:'Activity'};
async function api(path,body){const res=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await res.json()}catch{throw Error('The server could not complete this request.')}if(!res.ok)throw Error(data.detail||'Something went wrong.');return data;}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000)}
function admin(){return D.user.role==='admin'}function internal(){return D.user.role!=='customer'}
async function refresh(){D=await api('/workspace');render()}
function orbit(){return `<div class="orbit-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="orbit three"></div><div class="core">${mark()}</div><div class="orbit-label one">${icon('check',12)} Invoices in sync</div><div class="orbit-label two">${icon('repeat',12)} Built to recur</div><div class="orbit-label three">${icon('leaf',12)} Room to grow</div><i class="orbit-point"></i></div>`}
function navButton(id,ic,extra=''){return `<button data-page="${id}" class="${page===id?'active':''}">${icon(ic)}${labels[id]}${extra}</button>`}
function render(){
  $('#app').innerHTML=`<aside class="sidebar">${brand()}<div class="workspace"><span class="workspace-logo">B</span><div><strong>Brightloop Software</strong><small>${internal()?'Business workspace':'Your customer portal'}</small></div>${icon('down',12)}</div><div class="nav-caption">Workspace</div><nav class="nav">${navButton('overview','grid')}${navButton('subscriptions','repeat',`<span class="count">${D.subscriptions.length}</span>`)}${navButton('catalog','box')}${navButton('invoices','file')}${navButton('payments','wallet')}${internal()?navButton('customers','users'):''}</nav>${internal()?`<div class="nav-caption" style="margin-top:30px">Intelligence</div><nav class="nav">${navButton('rehearsal','spark')}${navButton('reports','chart')}</nav>`:''}<div class="sidebar-foot"><nav class="nav">${navButton('activity','clock')}${admin()?navButton('settings','settings'):''}</nav><div class="help-box"><strong style="font-size:11px">${icon('leaf',15)} A little more clarity.</strong><p>${internal()?'See your next billing cycle before it happens.':'Your subscriptions, all in one place.'}</p><button data-page="${internal()?'rehearsal':'subscriptions'}">${internal()?'Try billing rehearsal':'View your subscriptions'} ${icon('arrow',12)}</button></div><div class="profile">${avatar(D.user.name)}<div><strong>${esc(D.user.name)}</strong><small>${esc(D.user.role)} account</small></div><button data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout',15)}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu')}</button><span>Workspace</span>${icon('chevron',11)}<strong>${labels[page]}</strong></div><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="Search workspace">${icon('search',15)}<span>Search anything...</span><kbd>Ctrl K</kbd></button><span class="demo-tag">Demo workspace</span><button class="icon-btn" data-page="activity" aria-label="Recent activity">${icon('clock',17)}</button>${avatar(D.user.name)}</div></header><div class="content" id="content"></div></main>`;
  const views={overview,subscriptions,catalog,invoices,payments,customers,rehearsal,reports,settings,activity}; $('#content').innerHTML=views[page]()+`<footer class="footer"><span>${icon('leaf',11)} A better rhythm for your business.</span><span><i class="dot"></i> Local demo · Data persists on this device</span></footer>`;
  if(page==='rehearsal')loadRehearsal();
}
function header(title,sub,actions='',eyebrow='YOUR WORKSPACE, IN HARMONY'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function metric(title,value,foot,ic,accent=''){return `<div class="metric"><div class="metric-top">${title}<span class="metric-icon">${icon(ic,15)}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${accent?`<span class="up">${accent}</span>`:''}${foot}</div></div>`}
function stats(){const active=D.subscriptions.filter(s=>s.status==='Active');const mrr=active.reduce((n,s)=>n+s.recurring_total*({daily:365/12,weekly:52/12,monthly:1,yearly:1/12}[s.interval]),0);const outstanding=D.invoices.filter(i=>i.status==='Confirmed').reduce((n,i)=>n+i.total-i.paid,0);const overdue=D.invoices.filter(i=>i.status==='Confirmed'&&i.due_date<D.today);const collected=D.payments.reduce((n,p)=>n+p.amount,0);return {active,mrr,outstanding,overdue,collected}}
function metrics(){const s=stats();return `<div class="metrics">${metric('Monthly recurring revenue',money(s.mrr),'Normalized · before tax','trend','MRR')}${metric('Active subscriptions',s.active.length,`${D.subscriptions.length} subscriptions in your workspace`,'repeat')}${metric('Total collected',money(s.collected),'Across all recorded payments','wallet')}${metric('Outstanding balance',money(s.outstanding),`${s.overdue.length} invoices need attention`,'clock')}</div>`}
function chart(){const months=Array.from({length:6},(_,i)=>{const d=new Date(D.today+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()-5+i);return {key:d.toISOString().slice(0,7),label:d.toLocaleDateString('en',{month:'short'})}});const values=months.map(m=>(chartMode==='revenue'?D.payments.filter(p=>p.date.startsWith(m.key)).reduce((n,p)=>n+p.amount,0):D.invoices.filter(p=>p.period.startsWith(m.key)&&p.status!=='Cancelled').reduce((n,p)=>n+p.total,0)));const max=Math.max(...values,100);const points=values.map((v,i)=>[38+i*91,150-v/max*125]);const path=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');return `<section class="panel"><div class="panel-head"><div><h2>Revenue overview</h2><p>A little perspective on your growth.</p></div><div class="segmented"><button data-chart="revenue" class="${chartMode==='revenue'?'selected':''}">Collected</button><button data-chart="billed" class="${chartMode==='billed'?'selected':''}">Billed</button></div></div><div class="chart-meta"><span class="legend"><i></i>${chartMode==='revenue'?'Collected payments':'Invoice totals'}</span><span>Last 6 months</span></div><div class="chart"><svg viewBox="0 0 520 170" preserveAspectRatio="none" role="img" aria-label="${chartMode==='revenue'?'Collected':'Billed'} revenue by month: ${months.map((m,i)=>m.label+' '+money(values[i])).join(', ')}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#cbd9b2" stop-opacity=".5"/><stop offset="100%" stop-color="#eef3e5" stop-opacity=".1"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="38" x2="505" y1="${25+i*42}" y2="${25+i*42}" stroke="#edf0e7" stroke-dasharray="3 4"/><text x="0" y="${28+i*42}">${Math.round(max/100/1000*(1-i/3))}k</text>`).join('')}<path d="${path} L493,155 L38,155 Z" fill="url(#chartFill)"/><path class="line" d="${path}" fill="none" stroke="#97af70" stroke-width="2.4" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#fff" stroke="#97af70" stroke-width="1.5"><title>${months[i].label}: ${money(values[i])}</title></circle>`).join('')}</svg></div><div class="chart-months">${months.map(m=>`<span>${m.label}</span>`).join('')}</div></section>`}
function health(){const s=stats(), total=D.subscriptions.length||1, active=s.active.length, paused=D.subscriptions.filter(s=>s.status==='Paused').length;return `<section class="panel"><div class="panel-head"><div><h2>Subscription health</h2><p>Every relationship, accounted for.</p></div>${icon('repeat',15)}</div><div class="health-body"><div class="health-ring"><div class="ring"><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="49" stroke="#eef0e8"/><circle cx="60" cy="60" r="49" stroke="#b6c897" stroke-dasharray="${active/total*308} 308" stroke-linecap="round"/></svg><div class="ring-center"><strong>${Math.round(active/total*100)}%</strong><small>active</small></div></div><div class="health-key"><span><i></i>Active<b>${active}</b></span><span><i style="background:#decba2"></i>Paused<b>${paused}</b></span><span><i style="background:#e6e9de"></i>Other<b>${D.subscriptions.length-active-paused}</b></span></div></div><div class="health-alert">${icon(s.overdue.length?'alert':'check',16)}<div><strong>${s.overdue.length?s.overdue.length+' invoices need a little nudge.':'You’re all caught up.'}</strong><br>${s.overdue.length?'A timely follow-up goes a long way.':'No overdue invoices in your workspace.'}</div><button data-page="invoices" aria-label="View invoices">${icon('arrow',14)}</button></div></div></section>`}
function overview(){return header(`A little clarity. A lot of possibility.`,`Here’s how your business is flowing, ${esc(D.user.name.split(' ')[0])}.`,btn('Export report','export','download')+btn('New subscription','new-sub','plus','primary'))+`<section class="hero"><div class="hero-copy"><div class="pill"><i class="dot"></i> ${internal()?'INTRODUCING BILLING REHEARSAL':'YOUR NEXT CHAPTER'}</div><h2>${internal()?'Your next billing cycle.<br>Minus the surprises.':'Good things deserve<br>a steady rhythm.'}</h2><p>${internal()?'Preview upcoming invoices, spot revenue at risk, and make your next billing day feel effortless.':'Manage your subscriptions, track invoices and stay in control of what comes next.'}</p><button class="text-link" data-page="${internal()?'rehearsal':'subscriptions'}">${internal()?'Take a look ahead':'Explore your subscriptions'} ${icon('arrow',13)}</button></div>${orbit()}</section>`+metrics()+`<div class="middle-grid">${chart()}${health()}</div>`+subTable(true)}
function subscriptions(){return header('Subscriptions','Every customer relationship, from the first hello to the next renewal.',btn('New subscription','new-sub','plus','primary'),'BUILT FOR THE LONG RUN')+subTable(false)}
function subTable(compact=false){const filters=['All','Active','Paused','Quotation'];let list=D.subscriptions.filter(s=>(subFilter==='All'||s.status===subFilter)&&(!search||`${s.customer} ${s.plan} ${s.id}`.toLowerCase().includes(search.toLowerCase())));const shown=compact?list.slice(0,5):list;return `<section class="panel" id="subscription-panel"><div class="panel-head"><div><h2>${compact?'Your subscriptions':'Subscription directory'} <span class="tag" style="margin-left:7px">${D.subscriptions.length}</span></h2><p>${compact?'Good relationships are worth keeping.':'A clear view of every stage of the journey.'}</p></div>${compact?'<button class="text-btn" data-page="subscriptions">View all '+icon('arrow',13)+'</button>':''}</div><div class="table-toolbar"><div class="tabs">${filters.map(f=>`<button data-filter="${f}" class="${subFilter===f?'selected':''}">${f} <b>${f==='All'?D.subscriptions.length:D.subscriptions.filter(s=>s.status===f).length}</b></button>`).join('')}</div><input class="input search-input" id="sub-search" placeholder="Search subscriptions..." aria-label="Search subscriptions" value="${esc(search)}"></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Plan</th><th>Status</th><th>Recurring amount</th><th>Next invoice</th><th></th></tr></thead><tbody>${shown.map(s=>`<tr><td>${customerCell(s.customer,'SUB-'+String(s.id).padStart(4,'0'),s.customer_id)}</td><td>${esc(s.plan)} <small>· ${s.quantity} seats</small></td><td>${badge(s.status)}</td><td style="font-weight:600">${money(s.recurring_total)} <small style="font-weight:400">/ ${s.interval==='yearly'?'yr':s.interval==='monthly'?'mo':s.interval==='weekly'?'wk':'day'}</small></td><td>${s.status==='Active'?fmtDate(s.next_bill):'—'}</td><td><button class="icon-btn" data-sub="${s.id}" aria-label="Open subscription for ${esc(s.customer)}">${icon('chevron',14)}</button></td></tr>`).join('')}</tbody></table>${!shown.length?empty('No subscriptions here yet.','Create one to start a new customer journey.'):''}</div><div class="table-foot"><span>Showing ${shown.length} of ${list.length} subscriptions</span><span>All amounts in INR</span></div></section>`}
function empty(title,desc){return `<div class="empty"><h3>${title}</h3><p>${desc}</p></div>`}
function catalog(){return header('Room for every kind of growth.','Thoughtful products. Flexible plans. A recurring relationship that fits.',admin()?btn('Add product','new-product','box')+btn('Create plan','new-plan','plus','primary'):'','YOUR OFFERING')+`<div class="cards-grid">${D.plans.map((p,i)=>`<article class="plan-card ${i===1?'featured':''}"><div style="display:flex;align-items:center;justify-content:space-between"><h2>${esc(p.name)}</h2><span class="tag">${p.interval}</span></div><div class="plan-price">${money(p.price)}<small> / seat / ${({daily:'day',weekly:'week',monthly:'month',yearly:'year'}[p.interval])}</small></div><p>A flexible home for your team’s next chapter.</p><div class="plan-features"><span>${icon('users',14)} From ${p.min_quantity} ${p.min_quantity===1?'seat':'seats'}</span><span>${icon('repeat',14)} ${p.can_renew?'Renew when you’re ready':'Fixed term'}</span><span>${icon('check',14)} ${p.can_pause?'Pause when life happens':'Continuous service'}</span><span>${icon('clock',14)} Available until ${fmtDate(p.end_date)}</span></div>${btn('Start with '+esc(p.name),'plan-'+p.id,'arrow',i===1?'primary':'')}</article>`).join('')}</div><section class="panel section-spacer"><div class="panel-head"><div><h2>Product library</h2><p>The building blocks of a great subscription.</p></div>${icon('box',18)}</div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Type</th><th>Sales price</th>${internal()?'<th>Cost price</th>':''}<th>Variant</th></tr></thead><tbody>${D.products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small style="display:block;margin-top:5px">${esc(p.notes)}</small></td><td>${esc(p.type)}</td><td>${money(p.price)}</td>${internal()?`<td>${money(p.cost)}</td>`:''}<td>${esc(p.variant)||'Standard'} ${p.variant?'(+'+money(p.variant_price)+')':''}</td></tr>`).join('')}</tbody></table></div></section>${internal()?`<section class="panel section-spacer"><div class="panel-head"><div><h2>Quotation templates</h2><p>A head start on your next customer relationship.</p></div>${admin()?btn('Add template','new-template','plus'):''}</div>${D.templates.map(t=>`<div style="padding:16px 23px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line)"><div><strong style="font-size:12px">${esc(t.name)}</strong><p class="subtitle">${t.quantity} seats · Quote valid for ${t.valid_days} days</p></div>${btn('Use template','template-'+t.id,'arrow')}</div>`).join('')}</section>`:''}`}
function invoiceStatus(i){return i.status==='Confirmed'&&i.due_date<D.today?'Overdue':i.status}
function invoices(){const st=stats();return header('Invoices, without the busywork.','From first draft to final payment. Every detail in its place.',internal()?btn('Run due billing','run-billing','play','primary'):'','THE DETAILS THAT COUNT')+`<div class="metrics">${metric('Total invoiced',money(D.invoices.filter(i=>i.status!=='Cancelled').reduce((n,i)=>n+i.total,0)),'Excludes cancelled invoices','file')}${metric('Collected',money(st.collected),'All recorded payments','wallet')}${metric('Outstanding',money(st.outstanding),'Confirmed, unpaid balances','clock')}${metric('Overdue invoices',st.overdue.length,'Ready for a thoughtful follow-up','alert')}</div><section class="panel"><div class="panel-head"><h2>Invoice register</h2><span class="tag">${D.invoices.length} invoices</span></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Status</th><th>Total</th><th>Balance</th><th>Due date</th><th></th></tr></thead><tbody>${D.invoices.map(i=>`<tr><td><strong>INV-${String(i.id).padStart(4,'0')}</strong></td><td>${esc(i.customer)}</td><td>${badge(invoiceStatus(i))}</td><td>${money(i.total)}</td><td>${i.status==='Cancelled'?'—':money(i.total-i.paid)}</td><td>${fmtDate(i.due_date)}</td><td><button class="text-btn" data-invoice="${i.id}">View ${icon('arrow',12)}</button></td></tr>`).join('')}</tbody></table>${!D.invoices.length?empty('A clean slate.','Invoices will appear here when billing runs.'):''}</div></section>`}
function payments(){return header('Every payment, accounted for.','A reliable record of the money coming in.',btn('Export payments','export-payments','download'),'FOLLOW THE FLOW')+`<section class="panel"><div class="panel-head"><h2>Payment history</h2><span class="tag">${D.payments.length} payments</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Invoice</th><th>Method</th><th>Amount</th><th>Recorded on</th><th>Note</th></tr></thead><tbody>${D.payments.map(p=>`<tr><td>PAY-${String(p.id).padStart(4,'0')}</td><td><button class="text-btn" data-invoice="${p.invoice_id}">INV-${String(p.invoice_id).padStart(4,'0')}</button></td><td>${esc(p.method)}</td><td><strong>${money(p.amount)}</strong></td><td>${fmtDate(p.date)}</td><td>${esc(p.note)||'—'}</td></tr>`).join('')}</tbody></table>${!D.payments.length?empty('The beginning of a good flow.','Record a payment from a confirmed invoice to see it here.'):''}</div></section>`}
function customers(){return header('People behind the numbers.','A little context makes every conversation better.','','YOUR CUSTOMER COMMUNITY')+`<div class="cards-grid">${D.customers.map(c=>{const subs=D.subscriptions.filter(s=>s.customer_id===c.id);const balance=D.invoices.filter(i=>subs.some(s=>s.id===i.subscription_id)&&i.status==='Confirmed').reduce((n,i)=>n+i.total-i.paid,0);return `<article class="plan-card">${customerCell(c.name,c.email,c.id)}<div class="plan-features"><span>${icon('repeat',14)} ${subs.length} subscriptions</span><span>${icon('wallet',14)} ${money(balance)} outstanding</span></div>${btn('View journey','customer-'+c.id,'arrow')}</article>`}).join('')}</div>`}
function rehearsal(){return header('Look ahead. Move with confidence.','Your billing cycle, rehearsed before it becomes real.','','A LITTLE FORESIGHT GOES A LONG WAY')+`<div class="bill-banner"><div><div class="eyebrow">BILLING REHEARSAL</div><h2>No surprises on billing day.</h2><p>Preview the exact invoices your current subscriptions will generate. Check discounts, spot overdue balances, and see your expected billing before you run it.</p></div>${btn('Create today’s drafts','run-billing','play','orange')}</div><div id="rehearsal-metrics"></div><section class="panel"><div class="panel-head"><div><h2>Your next billing cycle</h2><p>A preview based on your current subscription data.</p></div><span class="tag">Preview only</span></div><div class="rehearsal-controls"><span>Look ahead</span><input type="range" min="0" max="90" value="${rehearsalDays}" id="horizon" aria-label="Billing preview days"><strong id="horizon-value">${rehearsalDays} days</strong></div><div id="rehearsal-table">${empty('Getting your preview ready…','Checking billing dates and discount eligibility.')}</div><div class="rehearsal-disclaimer">This preview creates no invoices. Billing runs create drafts for dates due today or earlier. Paused subscriptions and already billed periods are excluded. Forecasts assume plans and subscription status stay unchanged.</div></section>`}
let rehearsalSequence=0;
async function loadRehearsal(){const seq=++rehearsalSequence;try{const r=await api('/rehearsal?days='+rehearsalDays);if(seq!==rehearsalSequence||page!=='rehearsal')return;rehearsalData=r;$('#rehearsal-metrics').innerHTML=`<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Expected billing',money(r.total),'Including taxes and discounts','trend')}${metric('Upcoming invoices',r.items.length,`Over the next ${r.days} days`,'file')}${metric('Needs review',money(r.at_risk),'Invoices with flagged conditions','alert')}</div>`;$('#rehearsal-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Billing date</th><th>Before tax</th><th>Discount</th><th>Total</th><th>Readiness</th></tr></thead><tbody>${r.items.map(i=>`<tr><td><strong>${esc(i.customer)}</strong><p class="subtitle" style="font-size:9px;margin-top:4px">${esc(i.plan)} · SUB-${String(i.subscription_id).padStart(4,'0')}</p></td><td>${fmtDate(i.period)}</td><td>${money(i.subtotal)}</td><td>${i.discount?'-'+money(i.discount):'—'}</td><td><strong>${money(i.total)}</strong></td><td>${i.risk?'<span class="badge overdue">Review</span><div class="risk-note">'+esc(i.risk)+'</div>':'<span class="badge active">Ready</span>'}</td></tr>`).join('')}</tbody></table>${!r.items.length?empty('A quiet stretch ahead.','No unbilled subscription periods fall within this horizon.'):''}</div>`}catch(e){toast(e.message)}}
function reportContent(){const s=stats();return header('See the bigger picture.','Clear signals from your subscriptions, invoices, and payments.',btn('Export report','export','download'),'YOUR BUSINESS, IN PERSPECTIVE')+metrics()+`<div class="middle-grid">${chart()}${health()}</div><section class="panel"><div class="panel-head"><h2>Revenue by plan</h2><span class="tag">Active subscriptions · before tax</span></div><div class="table-wrap"><table><thead><tr><th>Plan</th><th>Active subscriptions</th><th>Seats</th><th>Monthly equivalent</th><th>Revenue mix</th></tr></thead><tbody>${D.plans.map(p=>{const a=s.active.filter(a=>a.plan_id===p.id);const amount=a.reduce((n,a)=>n+a.recurring_total*({daily:365/12,weekly:52/12,monthly:1,yearly:1/12}[a.interval]),0);return `<tr><td>${esc(p.name)}</td><td>${a.length}</td><td>${a.reduce((n,a)=>n+a.quantity,0)}</td><td>${money(amount)}</td><td><div style="display:flex;align-items:center;gap:12px"><span style="height:5px;background:#b4c895;border-radius:3px;width:${s.mrr?amount/s.mrr*130:0}px"></span>${s.mrr?Math.round(amount/s.mrr*100):0}%</div></td></tr>`}).join('')}</tbody></table></div><p class="rehearsal-disclaimer">MRR normalizes weekly plans using 52/12 and daily plans using 365/12. It excludes tax and one-time invoice discounts. Collected revenue reflects recorded payments, not a bank reconciliation.</p></section>`}
function activity(){return header('The story so far.','Every meaningful moment, in one shared timeline.','','YOUR WORKSPACE JOURNAL')+`<section class="panel"><div class="panel-head"><h2>Recent activity</h2><span class="tag">Latest ${D.events.length} events</span></div><div class="activity-list timeline">${D.events.map(e=>timelineItem(e)).join('')||empty('Your story starts here.','Create a subscription to begin.')}</div></section>`}
function timelineItem(e){return `<div class="timeline-item"><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p><small>SUB-${String(e.subscription_id).padStart(4,'0')} · ${new Date(e.created_at).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div>`}
function settings(){return header('Make yourself at home.','The rules, people, and preferences behind your workspace.','','WORKSPACE SETTINGS')+`<div class="settings-grid"><section class="panel settings-card"><h2>Workspace team</h2><p>Only administrators can invite internal staff.</p>${D.team.map(u=>`<div class="row">${avatar(u.name,u.id)}<div><strong>${esc(u.name)}</strong><small style="display:block">${esc(u.email)}</small></div><span class="tag" style="margin-left:auto">${u.role}</span></div>`).join('')}<div style="margin-top:15px">${btn('Add staff member','new-staff','plus')}</div></section><section class="panel settings-card"><h2>Tax rules</h2><p>Rates are copied to new subscriptions. Existing invoice totals retain their original calculations.</p>${D.taxes.map(t=>`<div class="row"><strong>${esc(t.name)}</strong><span style="margin-left:auto">${t.rate/100}%</span></div>`).join('')}<div style="margin-top:15px">${btn('Add tax rule','new-tax','plus')}</div></section><section class="panel settings-card"><h2>Discounts</h2><p>A thoughtful offer, applied automatically when eligible.</p>${D.discounts.map(d=>`<div class="row"><div><strong>${esc(d.code)}</strong><small style="display:block;margin-top:5px">${d.kind==='percentage'?d.value/100+'%':money(d.value)} off · ${d.uses}/${d.max_uses} uses · until ${fmtDate(d.end_date)}</small></div></div>`).join('')}<div style="margin-top:15px">${btn('Create discount','new-discount','plus')}</div></section><section class="panel settings-card"><h2>Local email outbox</h2><p>Email is queued locally for this demo. Connect an email provider before sending real reset links or invoice notifications.</p>${D.outbox.length?D.outbox.map(m=>`<div class="row" style="align-items:flex-start"><div>${icon('mail',15)}</div><div><strong>${esc(m.subject)}</strong><small style="display:block;margin:5px 0">To ${esc(m.recipient)}</small>${m.body.startsWith('/reset?')?`<a class="text-btn" href="${esc(m.body)}">Open password reset ${icon('arrow',12)}</a>`:`<small>${esc(m.body)}</small>`}</div></div>`).join(''):'<div class="inline-info">No messages queued yet.</div>'}</section></div>`}

function modal(title,sub,body,wide=false){modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="drawer-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close',19)}</button></div>${sub?`<p>${sub}</p>`:''}${body}</section></div>`;document.body.classList.add('no-scroll');setTimeout(()=>$('.modal input,.modal select,.modal button')?.focus(),50)}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('no-scroll');modalReturnFocus?.focus()}
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra} required></div>`}
function select(label,name,options,value=''){return `<div class="field"><label for="f-${name}">${label}</label><select class="input" id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`}
function check(label,name,value=true){return `<label class="field check-field"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`}
function form(title,sub,fields,submit,onSubmit){modal(title,sub,`<form id="modal-form"><div class="form-grid">${fields}</div><div class="form-error" role="alert"></div><div class="form-actions">${btn('Cancel','close-modal')}<button class="btn primary" type="submit">${submit}${icon('arrow',13)}</button></div></form>`);$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=Object.fromEntries(new FormData(f));f.querySelectorAll('input[type=checkbox]').forEach(x=>b[x.name]=x.checked);const button=f.querySelector('[type=submit]');button.disabled=true;try{await onSubmit(b);closeModal();await refresh()}catch(err){f.querySelector('.form-error').textContent=err.message;button.disabled=false}})}
function newSub(planId='',templateId=''){const t=D.templates.find(t=>t.id===+templateId),p=D.plans.find(p=>p.id===+(t?.plan_id||planId))||D.plans[0];const end=new Date(D.today+'T12:00:00');end.setFullYear(end.getFullYear()+1);form(t?'Start from '+esc(t.name):'A new beginning.',t?`This quotation template is valid for ${t.valid_days} days. Review the plan and seats before creating a draft.`:'Choose a customer, a plan, and the details. Your subscription starts as a draft.',`${internal()?select('Customer','customer_id',D.customers.map(c=>[c.id,c.name])):''}${select('Plan','plan_id',D.plans.map(p=>[p.id,p.name+' · '+money(p.price)+' / '+p.interval]),p.id)}${select('Product','product_id',D.products.map(p=>[p.id,p.name]),t?.product_id||1)}${field('Seats','quantity','number',t?.quantity||p.min_quantity,'min="1" max="100000"')}${field('Start date','start_date','date',D.today)}${field('Expiry date','end_date','date',end.toISOString().slice(0,10))}${select('Tax rule','tax_id',D.taxes.map(t=>[t.id,t.name+' · '+t.rate/100+'%']))}${field('Payment terms (days)','payment_terms','number',14,'min="0" max="365"')}${internal()?select('Discount','discount_id',[['','No discount'],...D.discounts.map(d=>[d.id,d.code])]):''}${check('Include product variant surcharge','variant',false)}`,'Create draft',async b=>{b.template_id=t?.id;b.lines=[...document.querySelectorAll('.extra-line')].map(row=>({product_id:row.querySelector('select').value,quantity:row.querySelector('input').value}));await api('/subscriptions',b);toast('A new subscription journey has begun.')});const extra=document.createElement('div');extra.innerHTML='<div class="section-spacer"><h3>Additional product lines</h3><p class="subtitle">Add-ons use the product sales price per billing interval.</p><div id="extra-lines"></div><button type="button" class="btn" id="add-line" style="margin-top:12px">+ Add product line</button></div>';$('#modal-form .form-grid').after(extra);$('#add-line').onclick=()=>{const row=document.createElement('div');row.className='extra-line';row.style.cssText='display:flex;gap:8px;margin-top:10px';row.innerHTML='<select class="input" aria-label="Additional product">'+D.products.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+money(p.price)+'</option>').join('')+'</select><input class="input" style="width:80px" type="number" min="1" max="100000" value="1" aria-label="Additional quantity"><button type="button" aria-label="Remove line">×</button>';row.querySelector('button').onclick=()=>row.remove();$('#extra-lines').append(row)};}
function subDetail(id){const s=D.subscriptions.find(s=>s.id===+id);if(!s)return;const p=D.plans.find(p=>p.id===s.plan_id);const stages=['Draft','Quotation','Confirmed','Active','Closed'];const statusIndex=stages.indexOf(s.status);let actions=[];if(internal()){if(s.status==='Draft')actions.push(['Create quotation','quote']);if(s.status==='Quotation')actions.push(['Confirm subscription','confirm']);if(s.status==='Confirmed')actions.push(['Activate subscription','activate'])}if(s.status==='Active'&&p.can_pause)actions.push(['Pause','pause']);if(s.status==='Paused')actions.push(['Resume','resume']);if(['Active','Paused'].includes(s.status)&&p.can_close)actions.push(['Close subscription','close']);if(s.status==='Closed'&&p.can_renew)actions.push(['Renew for one year','renew']);modal('The customer journey.','SUB-'+String(s.id).padStart(4,'0'),`<div class="detail-summary"><div>${customerCell(s.customer,s.plan+' · '+s.quantity+' seats',s.customer_id)}</div>${badge(s.status)}</div><div class="detail-grid"><div><small>Recurring amount</small><strong>${money(s.recurring_total)} / ${s.interval} before tax</strong></div><div><small>Next invoice</small><strong>${fmtDate(s.next_bill)}</strong></div><div><small>Started</small><strong>${fmtDate(s.start_date)}</strong></div><div><small>Expires</small><strong>${fmtDate(s.end_date)}</strong></div></div>${s.quote_expires&&['Draft','Quotation'].includes(s.status)?`<div class="inline-info">Quotation valid until ${fmtDate(s.quote_expires)}</div>`:''}<div class="lifecycle">${stages.map((v,i)=>`<span class="${i<=statusIndex?'done':''}">${v}</span>`).join('')}</div><div class="actions" style="flex-wrap:wrap">${actions.map(([label,a])=>btn(label,'transition-'+s.id+'-'+a,a==='close'?'close':'arrow',a==='close'?'danger':'primary')).join('')}</div><h3 style="margin-top:28px">Every step tells a story.</h3><div class="timeline">${D.events.filter(e=>e.subscription_id===s.id).map(timelineItem).join('')}</div>`)}
function invoiceDetail(id){const i=D.invoices.find(i=>i.id===+id);if(!i)return;const s=D.subscriptions.find(s=>s.id===i.subscription_id);modal('A clear record.','Invoice details and payment history.',`<div class="invoice-paper">${brand()}<div style="display:flex;justify-content:space-between"><div><h2>INV-${String(i.id).padStart(4,'0')}</h2><p class="subtitle">Brightloop Software<br>Bill to: ${esc(i.customer)}<br>${esc(s.email)}</p></div><div style="text-align:right">${badge(invoiceStatus(i))}<p class="subtitle">Period: ${fmtDate(i.period)}<br>Due: ${fmtDate(i.due_date)}</p></div></div><div class="table-wrap" style="margin-top:25px"><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.quantity}</td><td>${exactMoney(l.unit_price)}</td><td>${exactMoney(l.quantity*l.unit_price)}</td></tr>`).join('')}</tbody></table></div><div class="invoice-totals"><p><span>Subtotal</span><span>${exactMoney(i.subtotal)}</span></p><p><span>Discount</span><span>−${exactMoney(i.discount)}</span></p><p><span>Tax</span><span>${exactMoney(i.tax)}</span></p><p><span>Paid</span><span>${exactMoney(i.paid)}</span></p><p><span>${i.status==='Cancelled'?'Cancelled total':'Balance due'}</span><span>${exactMoney(i.status==='Cancelled'?i.total:i.total-i.paid)}</span></p></div></div><div class="actions" style="flex-wrap:wrap">${btn('Print / PDF','print','download')}${internal()?(i.status==='Draft'?btn('Confirm invoice','invoice-confirm-'+i.id,'check','primary'):'')+(i.status==='Confirmed'?btn('Record payment','payment-'+i.id,'wallet','primary'):'')+(['Confirmed','Paid'].includes(i.status)?btn('Queue email','invoice-send-'+i.id,'mail'):'')+(['Draft','Confirmed'].includes(i.status)&&!i.paid?btn('Cancel invoice','invoice-cancel-'+i.id,'close','danger'):''):''}</div>`,true)}
function recordPayment(id){const i=D.invoices.find(i=>i.id===+id);const key=crypto.randomUUID();form('Keep the flow going.','Record a payment received outside Cadence. This does not charge a card or move money.',field('Amount (INR)','amount','number',((i.total-i.paid)/100).toFixed(2),'min="0.01" step="0.01" max="'+((i.total-i.paid)/100)+'"')+select('Payment method','method',['Bank transfer','Card','Cash','UPI'].map(x=>[x,x]))+field('Payment date','date','date',D.today,'max="'+D.today+'"')+field('Reference or note','note','text','','maxlength="300"'),'Record payment',async b=>{await api('/invoices/'+id+'/pay',{...b,idempotency_key:key});toast('Payment recorded. The invoice balance is up to date.')})}
function catalogForm(kind){const tomorrow=new Date(D.today+'T12:00:00');tomorrow.setFullYear(tomorrow.getFullYear()+1);const future=tomorrow.toISOString().slice(0,10);let title,fields,endpoint=kind;
  if(kind==='products'){title='A new building block.';fields=field('Product name','name')+select('Type','type',[['Software','Software'],['Service','Service'],['Add-on','Add-on']])+field('Sales price (INR)','price','number',49,'min="0" step="0.01"')+field('Cost price (INR)','cost','number',10,'min="0" step="0.01"')+field('Notes','notes')+field('Variant name','variant','text','Odoo')+field('Variant surcharge (INR)','variant_price','number',560,'min="0" step="0.01"')}
  if(kind==='plans'){title='Make room for growth.';fields=field('Plan name','name')+field('Price per seat (INR)','price','number',129,'min="0" step="0.01"')+select('Billing interval','interval',['daily','weekly','monthly','yearly'].map(x=>[x,x]),'monthly')+field('Minimum seats','min_quantity','number',1,'min="1"')+field('Available from','start_date','date',D.today)+field('Available until','end_date','date',future)+check('Close automatically at expiry','auto_close')+check('Allow pausing','can_pause')+check('Allow early closure','can_close')+check('Allow renewal','can_renew')}
  if(kind==='taxes'){title='A simple tax rule.';fields=field('Rule name','name')+field('Rate (%)','rate','number',18,'min="0" max="100" step="0.01"')}
  if(kind==='discounts'){title='A thoughtful offer.';fields=field('Discount code','code')+select('Discount type','kind',[['percentage','Percentage'],['fixed','Fixed amount (INR)']])+field('Value (% or INR)','value','number',20,'min="0" step="0.01"')+field('Minimum seats','min_quantity','number',1,'min="1"')+field('Minimum purchase (INR)','min_amount','number',0,'min="0" step="0.01"')+field('Usage limit','max_uses','number',100,'min="1"')+field('Starts','start_date','date',D.today)+field('Ends','end_date','date',future)+select('Applies to','product_id',[['','Whole subscription'],...D.products.map(p=>[p.id,p.name])])}
  if(kind==='templates'){title='Give your next quote a head start.';fields=field('Template name','name')+select('Plan','plan_id',D.plans.map(p=>[p.id,p.name]))+select('Product','product_id',D.products.map(p=>[p.id,p.name]))+field('Seats','quantity','number',1,'min="1"')+field('Quote validity (days)','valid_days','number',30,'min="1"')}
  if(kind==='staff'){title='A new face on the team.';fields=field('Full name','name')+field('Email address','email','email')+field('Initial password','password','password','','minlength="9"');}
  form(title,'Changes are saved to this workspace.',''+fields,'Save',async b=>{await api('/catalog/'+endpoint,b);toast('Saved. Your workspace is up to date.')})}
function exportCsv(payments=false){const rows=payments?[['Payment','Invoice','Amount INR','Method','Date','Note'],...D.payments.map(p=>[p.id,p.invoice_id,(p.amount/100).toFixed(2),p.method,p.date,p.note])]:[['Subscription','Customer','Plan','Status','Seats','Recurring INR','Interval','Next billing'],...D.subscriptions.map(s=>[s.id,s.customer,s.plan,s.status,s.quantity,(s.recurring_total/100).toFixed(2),s.interval,s.next_bill])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`cadence-${payments?'payments':'subscriptions'}-${D.today}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your export is ready.')}
function commandSearch(){modal('Find your next step.','Search a customer, subscription, or workspace page.',`<input class="input" id="command-input" placeholder="Try ‘invoices’ or a customer name…" aria-label="Search workspace"><div class="command-results" id="command-results"></div>`);function results(q=''){$('#command-results').innerHTML=Object.entries(labels).filter(([k,v])=>(internal()||!['settings','rehearsal','customers','reports'].includes(k))&&(admin()||k!=='settings')&&v.toLowerCase().includes(q)).map(([k,v])=>`<button data-page="${k}">${v}${icon('arrow',13)}</button>`).join('')+D.subscriptions.filter(s=>s.customer.toLowerCase().includes(q)).slice(0,5).map(s=>`<button data-sub="${s.id}">${esc(s.customer)}<small>${esc(s.plan)} · SUB-${s.id}</small></button>`).join('')}results();$('#command-input').addEventListener('input',e=>results(e.target.value.toLowerCase()))}

async function action(a){if(a==='menu')return $('.sidebar').classList.toggle('open');if(a==='close-modal')return closeModal();if(a==='logout'){await api('/logout',{});D=null;return renderLogin()}if(a==='new-sub')return newSub();if(a==='search')return commandSearch();if(a==='print')return window.print();if(a==='export'||a==='export-payments')return exportCsv(a==='export-payments');if(a.startsWith('plan-'))return newSub(a.split('-')[1]);if(a.startsWith('template-'))return newSub('',a.split('-')[1]);if(a.startsWith('payment-'))return recordPayment(a.split('-')[1]);if(a.startsWith('customer-')){const c=D.customers.find(c=>c.id===+a.split('-')[1]);modal(esc(c.name),'The customer’s subscription story.',D.subscriptions.filter(s=>s.customer_id===c.id).map(s=>`<div class="detail-summary"><div><h3>${esc(s.plan)}</h3><p>SUB-${String(s.id).padStart(4,'0')} · ${money(s.recurring_total)}</p></div><button class="text-btn" data-sub="${s.id}">View journey ${icon('arrow',13)}</button></div>`).join('')||empty('No subscriptions yet.','Their next chapter is still to come.'));return}if(a.startsWith('new-'))return catalogForm({product:'products',plan:'plans',tax:'taxes',discount:'discounts',template:'templates',staff:'staff'}[a.slice(4)]);if(a.startsWith('transition-')){const [,id,transition]=a.split('-');await api('/subscriptions/'+id+'/transition',{action:transition});closeModal();await refresh();toast('Subscription updated.');return subDetail(id)}if(a.startsWith('invoice-')){const [,act,id]=a.split('-');await api('/invoices/'+id+'/'+act,{});closeModal();await refresh();toast(act==='send'?'Email queued in the local demo outbox.':'Invoice updated.');return invoiceDetail(id)}if(a==='run-billing'){modal('Ready for billing day?','Create draft invoices for active subscriptions with unbilled periods due today or earlier.',`<div class="inline-info">Each period is billed once. Eligible discounts and taxes are applied automatically. Review and confirm the generated drafts before recording payments.</div><div class="form-actions">${btn('Not yet','close-modal')}${btn('Create due drafts','confirm-billing','play','primary')}</div>`);return}if(a==='confirm-billing'){const result=await api('/billing/run',{});closeModal();await refresh();toast(result.created?`${result.created} draft invoices created. Ready for your review.`:'All caught up. No unbilled periods are due.');return}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action],[data-page],[data-filter],[data-sub],[data-invoice],[data-chart],[data-demo],[data-login-mode]');if(!el)return;try{if(el.dataset.page){page=el.dataset.page;search='';subFilter='All';closeModal();render();window.scrollTo(0,0)}else if(el.dataset.filter){subFilter=el.dataset.filter;render()}else if(el.dataset.sub)subDetail(el.dataset.sub);else if(el.dataset.invoice)invoiceDetail(el.dataset.invoice);else if(el.dataset.chart){chartMode=el.dataset.chart;render()}else if(el.dataset.demo){el.disabled=true;await doLogin(el.dataset.demo,'CadenceDemo!2026')}else if(el.dataset.loginMode){loginMode=el.dataset.loginMode;renderLogin()}else{el.disabled=true;try{await action(el.dataset.action)}finally{if(el.isConnected)el.disabled=false}}}catch(err){toast(err.message);el.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='sub-search'){const pos=e.target.selectionStart;search=e.target.value;const content=$('#content');const old=content.querySelector('#subscription-panel');const wrap=document.createElement('div');wrap.innerHTML=subTable(page==='overview');old?.replaceWith(wrap.firstElementChild);$('#sub-search').focus();$('#sub-search').setSelectionRange(pos,pos)}if(e.target.id==='horizon'){rehearsalDays=+e.target.value;$('#horizon-value').textContent=rehearsalDays+' days'}});
document.addEventListener('change',e=>{if(e.target.id==='horizon')loadRehearsal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.ctrlKey||e.metaKey)&&e.key==='k'&&D){e.preventDefault();commandSearch()}if(e.key==='Tab'&&$('.modal')){const items=[...$('.modal').querySelectorAll('button:not([disabled]),input,select,a,textarea')].filter(el=>el.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
async function doLogin(email,password){await api('/login',{email,password});page='overview';await refresh()}
function renderLogin(){const token=new URLSearchParams(location.search).get('token');if(location.pathname==='/reset'&&token)loginMode='reset';const copy={login:['Welcome to a better rhythm.','Sign in to your workspace. Good things are ahead.'],signup:['Start something that lasts.','Create your customer account to explore plans and manage subscriptions.'],forgot:['Let’s get you back in.','We’ll queue a reset link for your registered email address.'],reset:['A fresh start.','Choose a new password to return to your workspace.']}[loginMode];$('#app').innerHTML=`<div class="login"><section class="login-story">${brand()}<div><div class="eyebrow" style="margin-top:55px;color:#afbf9e">SUBSCRIPTIONS, THOUGHTFULLY ORCHESTRATED</div><h1>Good business<br>has a <em>rhythm.</em></h1><p>A calmer way to manage subscriptions, nurture relationships, and keep revenue flowing.</p>${orbit()}</div><footer><span>Built for the long run.</span><span>© ${new Date().getFullYear()} Cadence</span></footer></section><div class="login-form-wrap"><div class="login-form"><div class="mobile-only">${brand()}</div><div class="eyebrow">A LITTLE CLARITY STARTS HERE</div><h2>${copy[0]}</h2><p>${copy[1]}</p><form id="auth-form">${loginMode==='signup'?field('Your full name','name'):''}${loginMode!=='reset'?field('Email address','email','email','','autocomplete="email"'):''}${loginMode!=='forgot'?field(loginMode==='reset'?'New password':'Password','password','password','','autocomplete="'+(loginMode==='login'?'current-password':'new-password')+'"'):''}<div class="login-error" role="alert"></div><button type="submit" class="btn primary">${{login:'Sign in to workspace',signup:'Create your account',forgot:'Send reset link',reset:'Update password'}[loginMode]}${icon('arrow',15)}</button></form><div class="login-links"><button data-login-mode="${loginMode==='login'?'signup':'login'}">${loginMode==='login'?'Create a customer account':'Back to sign in'}</button>${loginMode==='login'?'<button data-login-mode="forgot">Forgot password?</button>':''}</div>${loginMode==='login'?`<div class="login-divider">OR EXPLORE THE DEMO</div><div class="demo-buttons"><button class="btn" data-demo="admin@cadence.demo">${icon('shield',13)}Admin</button><button class="btn" data-demo="staff@cadence.demo">${icon('users',13)}Staff</button><button class="btn" data-demo="olivia@acme.demo">${icon('leaf',13)}Customer</button></div><p class="login-note">A realistic demo workspace with persistent data.<br>No account or credit card needed to explore.</p>`:'<p class="login-note">Passwords need more than 8 characters, including uppercase, lowercase and a special character.</p>'}</div></div></div>`;$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));const submit=e.currentTarget.querySelector('button');submit.disabled=true;try{if(loginMode==='login')await doLogin(b.email,b.password);else if(loginMode==='signup'){await api('/signup',b);await doLogin(b.email,b.password)}else if(loginMode==='forgot'){const r=await api('/reset-request',b);$('.login-error').style.color='#74885b';$('.login-error').textContent=r.message;submit.disabled=false}else{await api('/reset',{...b,token});history.replaceState({},'','/');loginMode='login';renderLogin();toast('Password updated. Sign in with your new password.')}}catch(err){$('.login-error').textContent=err.message;submit.disabled=false}})}
$('#app').innerHTML='<div class="skeleton"><div>'+brand()+'<p class="subtitle" style="margin-top:20px">Finding your rhythm…</p></div></div>';
if(location.pathname==='/reset')renderLogin();else api('/workspace').then(d=>{D=d;render()}).catch(()=>renderLogin());

let reportRange='all', reportPlan='';
function reports(){
 const full=D;
 const cutoff=reportRange==='all'?'0000-01-01':new Date(new Date(D.today+'T12:00:00').getTime()-Number(reportRange)*86400000).toISOString().slice(0,10);
 const subs=D.subscriptions.filter(s=>!reportPlan||String(s.plan_id)===reportPlan);
 const ids=new Set(subs.map(s=>s.id));
 const invoices=D.invoices.filter(i=>ids.has(i.subscription_id)&&i.period>=cutoff);
 const invoiceIds=new Set(invoices.map(i=>i.id));
 const allInvoiceIds=new Set(D.invoices.filter(i=>ids.has(i.subscription_id)).map(i=>i.id));
 D={...D,subscriptions:subs,invoices,payments:D.payments.filter(p=>allInvoiceIds.has(p.invoice_id)&&p.date>=cutoff)};
 const filters='<div class="filter-row"><div style="display:flex;gap:10px;flex-wrap:wrap"><select class="input" id="report-range" aria-label="Report date range">'+[['all','All time'],['30','Last 30 days'],['90','Last 90 days'],['180','Last 180 days']].map(([v,l])=>'<option value="'+v+'" '+(v===reportRange?'selected':'')+'>'+l+'</option>').join('')+'</select><select class="input" id="report-plan" aria-label="Report plan"><option value="">All plans</option>'+full.plans.map(p=>'<option value="'+p.id+'" '+(String(p.id)===reportPlan?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></div><p class="subtitle">Revenue follows your date filter. MRR reflects current active subscriptions.</p></div>';
 try{return reportContent().replace('<div class="metrics">',filters+'<div class="metrics">')}finally{D=full}
}
 document.addEventListener('change',e=>{if(e.target.id==='report-range'){reportRange=e.target.value;render()}if(e.target.id==='report-plan'){reportPlan=e.target.value;render()}});
